
const CURRENT_SUBMISSION_SCHEMA_VERSION=1;
const MINIMUM_SUPPORTED_SUBMISSION_SCHEMA_VERSION=0;
const submissionLegacyConditions={"own_victory_points_at_most":{"quantity_target":"your","quantity":"flux","comparison_operator":"<="},"opponent_victory_points_at_most":{"quantity_target":"opponent","quantity":"flux","comparison_operator":"<="},"opponent_victory_points_at_least":{"quantity_target":"opponent","quantity":"flux","comparison_operator":">="},"opponent_sync_at_most":{"quantity_target":"opponent","quantity":"sync","comparison_operator":"<="}};
const submissionLegacyQuantities={"cards_in_your_deck":{"quantity_target":"your","quantity":"cards_in_deck"},"cards_in_your_hand":{"quantity_target":"your","quantity":"cards_in_hand"},"cards_on_your_board":{"quantity_target":"your","quantity":"cards_on_board"},"your_flux":{"quantity_target":"your","quantity":"flux"},"your_ki":{"quantity_target":"your","quantity":"ki"},"your_bandwidth":{"quantity_target":"your","quantity":"bandwidth"},"your_sync":{"quantity_target":"your","quantity":"sync"},"cards_in_opponent_deck":{"quantity_target":"opponent","quantity":"cards_in_deck"},"cards_in_opponent_hand":{"quantity_target":"opponent","quantity":"cards_in_hand"},"cards_on_opponent_board":{"quantity_target":"opponent","quantity":"cards_on_board"},"opponent_flux":{"quantity_target":"opponent","quantity":"flux"},"opponent_ki":{"quantity_target":"opponent","quantity":"ki"},"opponent_bandwidth":{"quantity_target":"opponent","quantity":"bandwidth"},"opponent_sync":{"quantity_target":"opponent","quantity":"sync"}};
function cloneSubmissionValue(value){return JSON.parse(JSON.stringify(value))}
function migrateSubmissionRuleV0ToV1(source){
 if(!source||typeof source!=='object'||Array.isArray(source))throw Error('A program rule is malformed.');
 const rule=cloneSubmissionValue(source),legacy=submissionLegacyConditions[rule.condition_type];
 if(legacy){
  const fields=['quantity_threshold','victory_points_threshold','energy_threshold'].filter(key=>Object.hasOwn(rule,key));
  if(!fields.length)throw Error('A legacy threshold condition has no threshold.');
  const values=[...new Set(fields.map(key=>rule[key]))];
  if(values.length!==1||!Number.isSafeInteger(values[0])||values[0]<0||values[0]>65535)throw Error('A legacy threshold condition has contradictory threshold fields.');
  Object.assign(rule,legacy,{condition_type:'quantity_compare',quantity_threshold:values[0]});
  delete rule.victory_points_threshold;delete rule.energy_threshold;
 }else if(rule.condition_type==='quantity_compare'){
  const quantity=submissionLegacyQuantities[rule.quantity];
  if(quantity){if(rule.quantity_target!==undefined&&rule.quantity_target!==quantity.quantity_target)throw Error('A legacy quantity condition has a contradictory target.');Object.assign(rule,quantity)}
 }
 return rule;
}
const submissionMigrationSteps={0:source=>{const migrated=cloneSubmissionValue(source),program=migrated.program??[];if(!Array.isArray(program))throw Error('A submission program is malformed.');migrated.program=program.map(migrateSubmissionRuleV0ToV1);migrated.submission_schema_version=1;return migrated}};
function migrateSubmissionToLatest(source){
 if(!source||typeof source!=='object'||Array.isArray(source))throw Error('A submission is malformed.');
 let migrated=cloneSubmissionValue(source),version=migrated.submission_schema_version??0;
 if(!Number.isSafeInteger(version))throw Error('The submission schema version is invalid.');
 if(version<MINIMUM_SUPPORTED_SUBMISSION_SCHEMA_VERSION)throw Error('That submission is older than the supported migration floor.');
 if(version>CURRENT_SUBMISSION_SCHEMA_VERSION)throw Error('That submission was created by a newer client.');
 while(version<CURRENT_SUBMISSION_SCHEMA_VERSION){const step=submissionMigrationSteps[version];if(!step)throw Error('No submission migration exists for version '+version+'.');migrated=step(migrated);version++;if(migrated.submission_schema_version!==version)throw Error('A submission migration produced the wrong version.')}
 return migrated;
}

