function activeDecklist(){return Object.fromEntries(Object.entries(state.deck).filter(([,count])=>Number(count)>0).map(([id,count])=>[id,Number(count)]))}function deckIds(){return Object.keys(state.deck).filter(id=>Number(state.deck[id])>0)}function programCardIds(){const ids=new Set(deckIds());let changed=true;while(changed){changed=false;for(const id of [...ids]){const definition=card(id),related=[...(definition.adds_card_ids||[]),definition.signature_card_id];if(definition.mission_grants_signature_card_id&&(!definition.mission_signature_agent_card_id||ids.has(definition.mission_signature_agent_card_id)))related.push(definition.mission_grants_signature_card_id);for(const relatedId of related)if(relatedId&&!ids.has(relatedId)){ids.add(relatedId);changed=true}}}return [...ids]}function deckSize(){return Object.values(state.deck).reduce((total,count)=>total+(Number(count)>0?Number(count):0),0)}
