function reactionRuleDescription(rule){if(rule.trigger_type==='own_agent_would_be_deleted'){const ids=Array.isArray(rule.agent_card_ids)&&rule.agent_card_ids.length?rule.agent_card_ids.map(name).join(' → '):'any Agent';return 'If '+ids+' would be deleted, play '+name(rule.action_card_id)+'.'}const comparison={'>':'more than','>=':'at least','=':'exactly','<=':'at most','<':'fewer than'}[rule.comparison_operator]||rule.comparison_operator;const subject=rule.trigger_type==='opponent_would_lose_sync'?'opponent would lose Sync':'opponent would gain Flux';return 'If '+subject+' '+comparison+' '+rule.quantity_threshold+', play '+name(rule.action_card_id)+'.'}
function renderReactionEditor(){const deletion=$('reaction-trigger').value==='own_agent_would_be_deleted';$('reaction-comparison-wrap').hidden=deletion;$('reaction-threshold-wrap').hidden=deletion;$('reaction-agent-wrap').hidden=!deletion;renderReactionAgentOptions(state.reactionAgentChoice||reactionCardsOption);if(deletion){$('reaction-comparison').value='=';$('reaction-threshold').value='1'}const ids=reactionCardsForTrigger($('reaction-trigger').value),current=$('reaction-card').value;options($('reaction-card'),ids,ids.includes(current)?current:ids[0]);renderReactionAgentPicker()}
renderReactionProgram=function(){const ids=reactionCardsForTrigger($('reaction-trigger').value);$('add-reaction').disabled=!ids.length;$('add-reaction').textContent=state.editingReactionIndex===undefined?'Add reaction':'Update reaction';$('cancel-reaction-edit').hidden=state.editingReactionIndex===undefined;renderReactionEditor();$('reactions').innerHTML=state.reactions.map((rule,index)=>'<li data-reaction-row="'+index+'"><span class="rule-priority">'+(index+1)+'</span><span class="rule-copy"><strong>'+esc(reactionRuleDescription(rule))+'</strong><small>'+(index===0?'Highest priority reaction.':'Runs after the reactions above.')+'</small></span><button type="button" data-edit-reaction="'+index+'" aria-label="Edit reaction '+(index+1)+'">✎</button><button type="button" data-move-reaction="'+index+'" data-reaction-direction="-1" '+(index===0?'disabled':'')+' aria-label="Move reaction '+(index+1)+' up">↑</button><button type="button" data-move-reaction="'+index+'" data-reaction-direction="1" '+(index+1===state.reactions.length?'disabled':'')+' aria-label="Move reaction '+(index+1)+' down">↓</button><button type="button" data-remove-reaction="'+index+'" aria-label="Delete reaction '+(index+1)+'">×</button></li>').join('')||'<li class="empty-state">No reactions yet.</li>'}
function beginReactionEdit(index){const rule=state.reactions[index];if(!rule)return;state.editingReactionIndex=index;$('reaction-trigger').value=rule.trigger_type;state.reactionAgentSelection=Array.isArray(rule.agent_card_ids)?[...rule.agent_card_ids]:[];state.reactionAgentChoice=rule.trigger_type==='own_agent_would_be_deleted'&&state.reactionAgentSelection.length>1?reactionCardsOption:rule.trigger_type==='own_agent_would_be_deleted'&&state.reactionAgentSelection.length===1?state.reactionAgentSelection[0]:reactionCardsOption;$('reaction-comparison').value=rule.comparison_operator||'=';$('reaction-threshold').value=rule.quantity_threshold??0;renderReactionEditor();$('reaction-card').value=rule.action_card_id;renderReactionAgentPicker();$('reaction-program').scrollIntoView({block:'nearest'})}
