/* Cloudflare D1 deck persistence. The editor remains in-memory and the same
 * generated client is exported for the local host and GitHub Pages. */
const cloudAdapterScript=document.querySelector('script[src*="app.js"]');
const cloudAdapterBase=cloudAdapterScript?new URL(cloudAdapterScript.src):new URL(location.href);
const cloudAdapterUrl=new URL('engine/deck-store.js',cloudAdapterBase);if(cloudAdapterBase.search)cloudAdapterUrl.search=cloudAdapterBase.search;
const cloudAdapterReady=import(cloudAdapterUrl);
state.cloudRecords=[];state.cloudPlayer=null;state.cloudStore=null;state.cloudReady=false;state.cloudApplying=false;state.cloudAutosavePaused=false;state.cloudUnsaved=false;state.cloudPending=false;state.cloudSaveTimer=null;state.cloudSavePromise=null;state.cloudRecord=null;state.cloudConflict=null;
function cloudStatus(message,tone='info'){const cloud=$('cloud-status');if(cloud){cloud.textContent=message;cloud.classList.toggle('cloud-error',tone==='error')}if(state.cloudReady&&$('status')&&!state.running)$('status').textContent=message}
function cloudErrorMessage(error){return error?.message||String(error)}
function cloudRecordSubmission(record){const draft=cloneSimulationValue(record?.draft||{});return {...draft,owner_name:state.cloudPlayer?.display_name||$('owner').value.trim(),name:record.name,_cloud_id:record.id,_cloud_revision:record.revision,_cloud_display_order:record.display_order}}
function cloudSubmissionRecord(){const record=currentDeckRecord(),copy=cloneSimulationValue(record);for(const key of ['_cloud_id','_cloud_revision','_cloud_display_order','id','revision','display_order'])delete copy[key];return copy}
function cloudFormatMetadata(){return {submission_schema_version:Number(state.currentCloudSchemaVersion??CURRENT_SUBMISSION_SCHEMA_VERSION),format_fingerprint:String(state.exportFormatFingerprint||state.formatFingerprint||'')}}
function cloudStoreRecord(record){const index=state.cloudRecords.findIndex(candidate=>candidate.id===record.id);if(index<0)state.cloudRecords.push(record);else state.cloudRecords[index]=record;state.cloudRecords.sort((a,b)=>a.display_order-b.display_order||a.id.localeCompare(b.id));return record}
function cloudSetRecords(records){state.cloudRecords=[...(records||[])].sort((a,b)=>a.display_order-b.display_order||a.id.localeCompare(b.id));return state.cloudRecords}
function cloudCurrentRecord(){return state.cloudRecord?.id?state.cloudRecords.find(record=>record.id===state.cloudRecord.id)||state.cloudRecord:null}
function cloudSetUi(loggedIn,loading=false){const actions=document.querySelector('.deck-setup-actions'),newWrap=$('new-deck-wrap'),login=$('player-login'),switcher=$('switch-player'),owner=$('owner');if(actions)actions.hidden=!loggedIn;if(newWrap&&!loggedIn)newWrap.hidden=true;if(login){login.hidden=loggedIn;login.disabled=loading;login.textContent=loading?'Logging in…':'Enter / Log in'}if(switcher)switcher.hidden=!loggedIn;if(owner)owner.disabled=loggedIn}
/* These names are kept for the existing editor code, but are now an in-memory
 * view over D1 records. There is deliberately no deck-storage localStorage
 * fallback. */
savedDeckKey=function(owner,name){const found=(state.cloudRecords||[]).find(record=>record.name===name&&(record.player_id===state.cloudPlayer?.id||owner===state.cloudPlayer?.display_name));return found?.id||String(owner||'')+'::'+String(name||'')};
loadSavedDecks=function(){return state.cloudRecords.map(cloudRecordSubmission)};
saveSavedDecks=function(){return undefined};
savedDecksForOwner=function(owner){return state.cloudPlayer&&owner===state.cloudPlayer.display_name?state.cloudRecords.map(cloudRecordSubmission):[]};
renderSavedDecks=function(){const owner=$('owner').value.trim(),list=$('saved-decks');if(!state.cloudReady){list.innerHTML=owner?'<li class="empty-state">Log in to load cloud decks.</li>':'<li class="empty-state">Enter your name, then choose Enter / Log in.</li>';return}if(!state.cloudRecords.length){list.innerHTML='<li class="empty-state">No cloud decks yet. Create one to begin.</li>';return}list.innerHTML=state.cloudRecords.map(record=>'<li data-saved-deck="'+esc(record.id)+'" draggable="true" tabindex="0" aria-label="Open '+esc(record.name)+'"><span class="saved-deck-name">'+esc(record.name)+'</span><span class="saved-deck-actions"><button class="saved-deck-icon rename-saved-deck" type="button" data-rename-saved-deck="'+esc(record.id)+'" aria-label="Rename deck '+esc(record.name)+'" title="Rename deck">✎</button><button class="saved-deck-icon delete-saved-deck" type="button" data-delete-saved-deck="'+esc(record.id)+'" aria-label="Delete deck '+esc(record.name)+'" title="Delete deck">×</button></span></li>').join('')};
function cloudOpenRecord(record,view='deck'){if(!record)return;state.cloudRecord=record;state.cloudAutosavePaused=false;state.cloudUnsaved=false;state.cloudConflict=null;$('cloud-conflict').hidden=true;state.cloudApplying=true;try{legacyCloudApplySavedDeckRecord(cloudRecordSubmission(record),view)}finally{state.cloudApplying=false}cloudStatus('Saved to D1.');renderSavedDecks()}
const legacyCloudApplySavedDeckRecord=applySavedDeckRecord;
applySavedDeckRecord=function(record,view='deck'){const cloud=record?._cloudRecord;if(cloud){cloudOpenRecord(cloud,view);return}legacyCloudApplySavedDeckRecord(record,view)};
function cloudUniqueName(base){const used=new Set(state.cloudRecords.map(record=>record.name));const root=String(base||'Imported Deck').trim()||'Imported Deck';let candidate=root,suffix=2;while(used.has(candidate))candidate=root+' ('+(suffix++)+')';return candidate}
function cloudShowConflict(error){state.cloudAutosavePaused=true;state.cloudConflict=error?.current||null;const panel=$('cloud-conflict'),message=$('cloud-conflict-message'),reload=$('cloud-reload-copy');if(panel)panel.hidden=false;if(message)message.textContent=state.cloudConflict?'Choose whether to discard your stale draft or save it as a new deck.':'The cloud deck was deleted by another browser. Save your draft as a new deck or return to the list.';if(reload)reload.hidden=!state.cloudConflict;cloudStatus('Not saved. Resolve the cloud conflict before editing continues.','error')}
function cloudUpdateLocalRecord(record){state.cloudRecord=record;cloudStoreRecord(record);state.cloudUnsaved=false;state.cloudPending=false;state.cloudAutosavePaused=false;cloudStatus('Saved.')}
async function cloudWritePending(){if(!state.cloudPending)return state.cloudSavePromise||Promise.resolve();if(state.cloudAutosavePaused)return Promise.reject(new Error('Resolve the cloud conflict before saving.'));const target=cloudCurrentRecord();if(!target||!state.cloudStore)return;clearTimeout(state.cloudSaveTimer);state.cloudSaveTimer=null;state.cloudPending=false;const metadata=cloudFormatMetadata(),draft=cloudSubmissionRecord();state.cloudSavePromise=(async()=>{cloudStatus('Saving…');try{const updated=await state.cloudStore.update(target.id,target.revision,{draft,name:$('deck-name').value.trim(),submission_schema_version:metadata.submission_schema_version,format_fingerprint:metadata.format_fingerprint});cloudUpdateLocalRecord(updated)}catch(error){state.cloudUnsaved=true;if(error?.code==='revision_conflict'||error?.code==='deck_not_found')cloudShowConflict(error);else cloudStatus('Not saved. Retry when the cloud service is available.','error');throw error}finally{state.cloudSavePromise=null}})();return state.cloudSavePromise}
async function cloudFlushSave(){clearTimeout(state.cloudSaveTimer);state.cloudSaveTimer=null;if(state.cloudSavePromise)return state.cloudSavePromise;if(!state.cloudPending)return Promise.resolve();return cloudWritePending()}
function cloudScheduleSave(){if(!state.cloudReady||state.cloudApplying||!state.cloudRecord||state.cloudAutosavePaused)return;state.cloudPending=true;state.cloudUnsaved=false;cloudStatus('Saving…');clearTimeout(state.cloudSaveTimer);state.cloudSaveTimer=setTimeout(()=>cloudWritePending().catch(()=>{}),750)}
persistSelectedDeck=function(){cloudScheduleSave()};
function cloudApplyNewRecord(record,view='deck'){cloudStoreRecord(record);cloudOpenRecord(record,view)}

async function cloudLogin(){const name=$('owner').value.trim();if(!name){cloudStatus('Enter a player name first.','error');$('owner').focus();return}cloudSetUi(false,true);cloudStatus('Logging in…');try{const {DeckStore}=await cloudAdapterReady;state.cloudStore=new DeckStore({baseUrl:String(state.deckApiUrl||'')});const player=await state.cloudStore.login(name);state.cloudPlayer=player;state.simulationHistory=loadSimulationHistory();const listing=await state.cloudStore.list();cloudSetRecords(listing.decks);$('owner').value=player.display_name;persistPlayerName();state.cloudReady=true;cloudSetUi(true);await cloudMigrateLegacy();renderSavedDecks();cloudStatus(state.cloudRecords.length?'Cloud decks loaded.':'Logged in. Create your first cloud deck.');}catch(error){state.cloudReady=false;cloudSetUi(false);cloudStatus(cloudErrorMessage(error),'error');}}
async function cloudMigrateLegacy(){const raw=localStorage.getItem(deckStorageKey);if(raw===null)return;let source;try{source=JSON.parse(raw);if(!Array.isArray(source))throw Error('The legacy deck cache is not an array.')}catch(error){cloudStatus('Legacy decks were left untouched because the browser cache is malformed. '+cloudErrorMessage(error),'error');return}const matching=source.filter(deck=>deck&&typeof deck==='object'&&String(deck.owner_name||'').trim().normalize('NFKC').toLowerCase()===state.cloudPlayer.name_key);if(!matching.length)return;try{const {legacyImportFingerprint}=await cloudAdapterReady;const migrated=[];for(const deck of matching){const next=assertSubmissionReferencesAvailable(migrateSubmissionToLatest(deck)),legacyKey=String(deck.owner_name||'')+'::'+String(deck.name||'');migrated.push({legacy_key:legacyKey,import_key:await legacyImportFingerprint(legacyKey,next),name:String(next.name||'Imported Deck'),draft:next,submission_schema_version:Number(next.submission_schema_version??CURRENT_SUBMISSION_SCHEMA_VERSION),format_fingerprint:String(state.exportFormatFingerprint||state.formatFingerprint||'')})}const result=await state.cloudStore.importBrowserDecks(migrated);const followup=await state.cloudStore.list();const mapping=new Map(result.mappings.map(item=>[item.legacy_key,item.deck_id]));for(const deck of matching){const oldKey=String(deck.owner_name||'')+'::'+String(deck.name||'');const nextKey=mapping.get(oldKey);if(nextKey&&state.simulationHistory[oldKey]){state.simulationHistory[nextKey]=state.simulationHistory[oldKey];delete state.simulationHistory[oldKey]}}saveSimulationHistory();cloudSetRecords(followup.decks);localStorage.removeItem(deckStorageKey);for(let index=localStorage.length-1;index>=0;index--){const key=localStorage.key(index);if(key?.startsWith(deckStorageKey+'-backup-')||key?.startsWith(deckStorageKey+'-migration-'))localStorage.removeItem(key)}cloudStatus('Import complete: '+matching.length+' browser deck'+(matching.length===1?'':'s')+' moved to D1.');}catch(error){cloudStatus('Legacy decks were left untouched. Retry the import after fixing this: '+cloudErrorMessage(error),'error')}}
initializeBrowserDeckMigration=async function(){/* D1 login owns the migration barrier. */};
startNewDeck=async function(){if(!state.cloudReady){cloudStatus('Log in before creating a cloud deck.','error');return}try{await cloudFlushSave();const owner=state.cloudPlayer.display_name,name=$('deck-name').value.trim();if(!name){cloudStatus('Give the new deck a name first.','error');$('deck-name').focus();return}if(state.cloudRecords.some(record=>record.name_key===name.normalize('NFKC').toLowerCase())){cloudStatus('A cloud deck already has that name.','error');return}const metadata=cloudFormatMetadata(),created=await state.cloudStore.create({name,draft:{owner_name:owner,name,decklist:{},program:[],default_action:'play_random_card',random_card_ids:[],random_eligibility_configured:false,reactions:[],submission_schema_version:metadata.submission_schema_version},submission_schema_version:metadata.submission_schema_version,format_fingerprint:metadata.format_fingerprint});$('new-deck-wrap').hidden=true;$('new-deck-hint').hidden=true;cloudApplyNewRecord(created,'deck');cloudStatus('Created '+created.name+'.')}catch(error){cloudStatus('Could not create the cloud deck. '+cloudErrorMessage(error),'error')}};
loadSavedDeckByKey=async function(key){try{await cloudFlushSave();cloudOpenRecord(state.cloudRecords.find(record=>record.id===key),'deck')}catch(error){cloudStatus('Could not open that deck. '+cloudErrorMessage(error),'error')}};
renameSavedDeck=async function(key){const record=state.cloudRecords.find(candidate=>candidate.id===key);if(!record)return;const next=record.name;try{await cloudFlushSave();const updated=await state.cloudStore.update(record.id,record.revision,{name:next});cloudUpdateLocalRecord(updated);if(state.cloudRecord?.id===record.id){state.cloudRecord=updated;$('deck-name').value=updated.name;state.deckKey=updated.id}renderSavedDecks();cloudStatus('Deck renamed to '+updated.name+'.')}catch(error){if(error?.code==='revision_conflict'||error?.code==='deck_not_found')cloudShowConflict(error);else cloudStatus('Could not rename the deck. '+cloudErrorMessage(error),'error')}};
deleteSavedDeck=async function(key){const record=state.cloudRecords.find(candidate=>candidate.id===key);if(!record||!window.confirm('Delete saved deck "'+record.name+'"?'))return;try{await cloudFlushSave();await state.cloudStore.remove(record.id,record.revision);state.cloudRecords=state.cloudRecords.filter(candidate=>candidate.id!==record.id);if(state.cloudRecord?.id===record.id){state.cloudRecord=null;state.deckKey=null;state.deckReady=false;$('deck-setup').hidden=false;$('workflow-nav').hidden=true;cloudSetUi(true)}renderSavedDecks();cloudStatus('Deleted '+record.name+'.')}catch(error){if(error?.code==='revision_conflict'||error?.code==='deck_not_found')cloudShowConflict(error);else cloudStatus('Could not delete the deck. '+cloudErrorMessage(error),'error')}};
reorderSavedDecks=async function(fromKey,toKey){if(fromKey===toKey)return;try{await cloudFlushSave();const ids=state.cloudRecords.map(record=>record.id),from=ids.indexOf(fromKey),to=ids.indexOf(toKey);if(from<0||to<0)return;const [moved]=ids.splice(from,1);ids.splice(to,0,moved);cloudSetRecords(await state.cloudStore.reorder(ids));renderSavedDecks();cloudStatus('Deck order saved.')}catch(error){cloudStatus('Could not save deck order. '+cloudErrorMessage(error),'error')}};
copyTournamentDeck=async function(id){try{await cloudFlushSave();const entry=tournamentEntry(id),normalized=migrateTournamentSubmission(entry),owner=state.cloudPlayer?.display_name||$('owner').value.trim(),name=cloudUniqueName('Copy of '+(normalized.name||entry.player_name||'Tournament deck')),metadata=cloudFormatMetadata(),created=await state.cloudStore.create({name,draft:{...cloneSimulationValue(normalized),owner_name:owner,name},submission_schema_version:metadata.submission_schema_version,format_fingerprint:metadata.format_fingerprint});cloudApplyNewRecord(created,'deck');tournamentPanel().hidden=true;cloudStatus('Copied '+name+' to D1.');}catch(error){cloudStatus('Could not copy that tournament deck. '+cloudErrorMessage(error),'error')}};
importDeckFromClipboard=async function(){if(!state.cloudReady){cloudStatus('Log in before importing a deck.','error');return}try{await cloudFlushSave();if(!navigator.clipboard?.readText)throw Error('Clipboard access is unavailable in this browser.');const code=await navigator.clipboard.readText();if(!code.trim())throw Error('The clipboard is empty.');const {decodeSubmission}=await submissionCodecReady,payload=assertSubmissionReferencesAvailable(decodeSubmission(code,currentCodecCatalogs(),currentCodecCatalog().format_id)),owner=state.cloudPlayer.display_name,name=cloudUniqueName(payload.name||'Imported Deck'),metadata=cloudFormatMetadata(),created=await state.cloudStore.create({name,draft:{...payload,owner_name:owner,name},submission_schema_version:metadata.submission_schema_version,format_fingerprint:metadata.format_fingerprint});closeDeckSetup();cloudApplyNewRecord(created,'program');cloudStatus('Imported '+name+' into D1.')}catch(error){cloudStatus('Could not import the Discord code. '+cloudErrorMessage(error),'error')}};

const cloudUiRenderSavedDecks=renderSavedDecks, cloudUiStartNewDeck=startNewDeck, cloudUiLoadSavedDeckByKey=loadSavedDeckByKey, cloudUiRenameSavedDeck=renameSavedDeck, cloudUiDeleteSavedDeck=deleteSavedDeck, cloudUiReorderSavedDecks=reorderSavedDecks, cloudUiCopyTournamentDeck=copyTournamentDeck, cloudUiImportDeckFromClipboard=importDeckFromClipboard, cloudUiPersistSelectedDeck=persistSelectedDeck, cloudUiApplySavedDeckRecord=applySavedDeckRecord;
const rawCloudExport=typeof $('export-deck').onclick==='function'?$('export-deck').onclick:null;
$('export-deck').onclick=async()=>{try{await cloudFlushSave();if(state.cloudUnsaved)cloudStatus('Exporting an unsaved in-memory draft; it is not stored in D1.','error');if(rawCloudExport)await rawCloudExport()}catch(error){cloudStatus('Exporting this draft while it is not saved in D1. '+cloudErrorMessage(error),'error');if(rawCloudExport)await rawCloudExport()}};
$('export-deck-results').onclick=()=>$('export-deck').click();
