$('cloud-save-new').onclick=async()=>{try{const source=cloudSubmissionRecord(),metadata=cloudFormatMetadata(),owner=state.cloudPlayer.display_name,name=cloudUniqueName((source.name||$('deck-name').value)+' (conflict copy)'),created=await state.cloudStore.create({name,draft:{...source,owner_name:owner,name},submission_schema_version:metadata.submission_schema_version,format_fingerprint:metadata.format_fingerprint});$('cloud-conflict').hidden=true;cloudApplyNewRecord(created,'deck');cloudStatus('Saved your draft as '+name+'.')}catch(error){cloudStatus('Could not save the conflict as a new deck. '+cloudErrorMessage(error),'error')}};
$('cloud-return-list').onclick=async()=>{await cloudFlushSave().catch(()=>{});$('cloud-conflict').hidden=true;state.cloudConflict=null;state.cloudAutosavePaused=false;state.cloudRecord=null;state.deckReady=false;$('deck-setup').hidden=false;$('workflow-nav').hidden=true;cloudSetUi(true);renderSavedDecks()};
$('player-login').onclick=cloudLogin;
$('owner').onkeydown=event=>{if(event.key==='Enter'&&!state.cloudReady){event.preventDefault();cloudLogin()}};
$('switch-player').onclick=async()=>{await cloudFlushSave().catch(()=>{});state.cloudStore?.clearSession();state.cloudReady=false;state.cloudPlayer=null;state.cloudRecords=[];state.cloudRecord=null;state.deckReady=false;$('deck-setup').hidden=false;$('workflow-nav').hidden=true;$('owner').disabled=false;$('owner').value='';cloudSetUi(false);renderSavedDecks();cloudStatus('Enter another player name to switch.');};
