function legacyExportDeckCode(){const ids=state.pool.map(card=>card.card_id),index=new Map(ids.map((id,i)=>[id,i])),bytes=ids.map(id=>state.deck[id]||0);bytes.push(state.rules.length);for(const rule of state.rules){const condition={if_able:0,card_in_hand:1,own_victory_points_at_most:2,opponent_victory_points_at_most:3}[rule.condition_type],action={play_named_card:0,play_random_card:1,end_turn:2}[rule.action_type];if(condition===undefined||action===undefined)throw Error('This deck has an unsupported rule.');bytes.push((condition<<4)|action);if(condition===1)bytes.push(index.get(rule.condition_card_id));else if(condition===2||condition===3)bytes.push(rule.victory_points_threshold??rule.energy_threshold);if(action===0)bytes.push(index.get(rule.action_card_id));}return 'CD2'+btoa(String.fromCharCode(...bytes)).replaceAll('+','-').replaceAll('/','_').replaceAll('=','')}
