$('export-deck').onclick=async()=>{try{if(deckSize()<state.config.minimum_deck_size||deckSize()>state.config.maximum_deck_size)throw Error(deckMessage());if(state.rules.length>255)throw Error('A deck can export at most 255 program rules.');persistSelectedDeck();const code=exportDeckCode();await copyExportCode(code);$('status').textContent='Discord export code copied to your clipboard ('+code.length+' characters). Run /netdeck in Discord and paste it into the import box.'}catch(error){$('status').textContent='Could not export this deck. '+error.message}};
function midConditionText(type,threshold,cardId){if(type==='if_able')return 'if able';if(type==='card_in_hand')return name(cardId)+' is in your hand';if(type==='own_victory_points_at_most')return 'your Flux are '+threshold+' or less';return 'opponent Flux are '+threshold+' or less'}
function renderConditionParameters(){const type=$('condition-type').value,cardCondition=type==='card_is'&&deckIds().length>0,thresholdCondition=type!=='card_is'&&type!=='if_able';$('condition-card-wrap').hidden=!cardCondition;$('card-condition-wrap').hidden=!cardCondition;$('condition-energy-wrap').hidden=!thresholdCondition;renderRuleSentence()}
