function tournamentReplayEntry(playerId){const pair=tournamentState.selectedMatchup||tournamentState.data?.battles?.[tournamentState.matchIndex]||tournamentState.data?.matchups?.[tournamentState.matchIndex];if(!pair||typeof tournamentEntry!=='function')return;const discordUserId=playerId==='first'?pair.first_discord_user_id:pair.second_discord_user_id;return tournamentEntry(discordUserId)}
