let deckHideTimer=null,activeDeckPopover=null;function positionDeckPopover(){if(!activeDeckPopover)return;const{trigger,popover}=activeDeckPopover,rect=trigger.getBoundingClientRect(),width=popover.offsetWidth,height=popover.offsetHeight;let left=Math.min(window.innerWidth-width-8,Math.max(8,rect.left)),top=rect.bottom+8;if(top+height>window.innerHeight-8)top=Math.max(8,rect.top-height-8);popover.style.left=left+'px';popover.style.top=top+'px'}function clearDeckPopover(){if(activeDeckPopover?.popover)activeDeckPopover.popover.remove();activeDeckPopover=null}function scheduleDeckPopoverHide(){clearTimeout(deckHideTimer);deckHideTimer=setTimeout(()=>{if(!document.querySelector('[data-deck-view]:hover')&&!document.querySelector('.deck-view-popover:hover')&&!document.activeElement?.closest('[data-deck-view],.deck-view-popover'))clearDeckPopover()},160)}function showDeckPopover(trigger){clearTimeout(deckHideTimer);clearHandPopover();clearResourcePopover();const key=trigger.dataset.deckView,snapshot=state.deckViews?.[key];if(!snapshot)return;if(activeDeckPopover?.key===key){positionDeckPopover();return}clearDeckPopover();const popover=document.createElement('div');popover.className='hand-view-popover deck-view-popover';popover.dataset.deckPopover=key;popover.setAttribute('role','dialog');popover.setAttribute('aria-label',snapshot.playerName+' Deck');popover.innerHTML=deckPopoverMarkup(snapshot);document.body.append(popover);activeDeckPopover={key,trigger,popover};positionDeckPopover()}
