/* Frozen tournament programs use the same readable numeric-condition sentence. */
tournamentRuleText=function(rule){const condition=rule.condition_type==='quantity_compare'?'If '+quantityConditionText(rule):rule.condition_type==='if_able'?'If able':rule.condition_type==='card_in_hand'?'If '+tournamentCardName(rule.condition_card_id)+' is in your hand':rule.condition_type==='card_is'?'If '+tournamentCardName(rule.condition_card_id)+' is '+(rule.card_condition==='on_your_side_of_board'?'on your side of the board':'in your hand'):rule.condition_type==='own_victory_points_at_most'?'If Flux is '+rule.victory_points_threshold+' or less':rule.condition_type==='opponent_victory_points_at_most'?'If opponent Flux is '+rule.victory_points_threshold+' or less':rule.condition_type==='opponent_victory_points_at_least'?'If opponent Flux is '+rule.victory_points_threshold+' or more':'If opponent Sync is '+rule.victory_points_threshold+' or less';return condition+', '+tournamentRuleActionText(rule)+'.'};

function tournamentDeckCardName(cardId){return '<span class="tournament-card-name" tabindex="0" data-tournament-card-preview="'+esc(cardId)+'">'+esc(tournamentCardName(cardId))+'</span>'}
function tournamentCardPreview(cardId){const current=card(cardId),keyword=current.keyword_line?'<p class="card-keyword"><strong>'+esc(current.keyword_line)+'</strong></p>':'',density=(current.effect||'').length>400?' dense-card':'';return '<article class="builder-card'+density+'"><div class="card-titlebar"><h4>'+esc(current.display_name)+'</h4></div><div class="card-art-frame">'+(current.art_url?'<img src="'+esc(current.art_url)+'" alt="'+esc(current.art_alt||current.display_name)+'" style="object-position:'+esc(current.art_position||'center')+'">':'')+'</div><div class="card-typebar"><span>'+esc(current.card_kind_label||'Card')+'</span></div><div class="card-rules">'+keyword+'<p>'+esc(current.effect)+'</p></div></article>'}
function showTournamentCardPreview(target){document.querySelectorAll('.tournament-card-tooltip').forEach(node=>node.remove());const preview=document.createElement('div');preview.className='tournament-card-tooltip';preview.innerHTML=tournamentCardPreview(target.dataset.tournamentCardPreview);document.body.append(preview);const rect=target.getBoundingClientRect(),gap=12,width=preview.offsetWidth,height=preview.offsetHeight;let left=rect.right+gap,top=rect.top;if(left+width>window.innerWidth-8)left=rect.left-width-gap;left=Math.max(8,Math.min(left,window.innerWidth-width-8));top=Math.max(8,Math.min(top,window.innerHeight-height-8));preview.style.left=left+'px';preview.style.top=top+'px'}
function hideTournamentCardPreview(){document.querySelectorAll('.tournament-card-tooltip').forEach(node=>node.remove())}
