async function tournamentRulesFingerprint(){const script=document.querySelector('script[src*="app.js"]'),base=script?script.src:location.href,files=await Promise.all(['engine/engine.js','engine/cards.js'].map(path=>fetch(new URL(path,base)).then(response=>{if(!response.ok)throw Error('rules asset unavailable');return response.arrayBuffer()}))),bytes=new Uint8Array(files[0].byteLength+1+files[1].byteLength);bytes.set(new Uint8Array(files[0]));bytes[files[0].byteLength]=0;bytes.set(new Uint8Array(files[1]),files[0].byteLength+1);const digest=await crypto.subtle.digest('SHA-256',bytes);return Array.from(new Uint8Array(digest)).map(value=>value.toString(16).padStart(2,'0')).join('')}
