function tournamentReplaySubmission(entry){const submission=entry.submission,decklist={},known=new Set;for(const card of tournamentState.data?.manifest?.cards||[]){const id=card.card_id;known.add(id);if(Object.prototype.hasOwnProperty.call(submission.decklist,id))decklist[id]=submission.decklist[id]}for(const [id,count] of Object.entries(submission.decklist)){if(!known.has(id))decklist[id]=count}return {...submission,decklist}}
