/* Simulation history is browser-local and scoped to the selected saved deck. */
const simulationHistoryStorageKey='cybernet-simulation-history-v1';
function cloneSimulationValue(value){return value===undefined?undefined:JSON.parse(JSON.stringify(value))}
function loadSimulationHistory(){try{const value=JSON.parse(localStorage.getItem(simulationHistoryStorageKey)||'{}');return value&&typeof value==='object'&&!Array.isArray(value)?value:{}}catch(_error){return {}}}
function saveSimulationHistory(){try{localStorage.setItem(simulationHistoryStorageKey,JSON.stringify(state.simulationHistory))}catch(_error){}}
function simulationHistoryForDeck(){const entry=state.deckKey?state.simulationHistory[state.deckKey]:null;if(!entry)return null;if(entry.format_id!==state.formatId||entry.format_fingerprint!==state.formatFingerprint)return null;return entry}
function editorSimulationSnapshot(){return {submission:cloneSimulationValue(currentDeckPayload()),random_eligibility_configured:state.randomEligibilityConfigured===true}}
function simulationRunRecord(snapshot,matches){return {format_id:state.formatId||'inaugural',format_fingerprint:state.formatFingerprint||'',submission:cloneSimulationValue(snapshot.submission),random_eligibility_configured:snapshot.random_eligibility_configured===true,win_rates:Object.fromEntries(matches.map(match=>[match.opponent,browserWinRate(match)]))}}
function renderRevertButton(){const button=$('revert-to-previous-run');if(!button)return;const hasPrevious=Boolean(state.currentRun?.previous?.submission);const locked=state.revertLockRevision!==null&&state.revertLockRevision===state.editorRevision;button.hidden=!hasPrevious;button.disabled=state.running||locked}
function markEditorChanged(){state.editorRevision+=1;renderRevertButton()}
function restoreSimulationRun(record){const submission=record?.submission||{};$('owner').value=submission.owner_name||$('owner').value;$('deck-name').value=submission.name||$('deck-name').value;state.deck={...(submission.decklist||{})};state.rules=(submission.program||[]).map(rule=>({...rule}));state.defaultAction=submission.default_action||'play_random_card';state.randomEligibleCards=Array.isArray(submission.random_card_ids)?[...submission.random_card_ids]:Object.keys(state.deck);state.randomEligibilityConfigured=record?.random_eligibility_configured===undefined?Array.isArray(submission.random_card_ids):record.random_eligibility_configured===true;state.reactions=(submission.reactions||[]).map(rule=>({...rule}));state.selectedRule=undefined;renderDeck();renderRules();renderReactionProgram();renderDefaultAction();persistSelectedDeck()}
function startBrowserSimulation(){try{if(deckSize()<state.config.minimum_deck_size||deckSize()>state.config.maximum_deck_size){$('status').textContent=deckMessage();return}const opponents=Array.isArray(state.publicOpponents)&&state.publicOpponents.length?state.publicOpponents:tournamentSimulationOpponents();if(!opponents.length){$('status').textContent='No published tournament is available for simulations.';return}const snapshot=editorSimulationSnapshot(),previous=simulationHistoryForDeck();state.pendingRun={snapshot,previous};state.comparisonBrowserWinRates={...(previous?.win_rates||{})};state.running=true;state.session='browser';state.match=null;state.browserMatch=null;state.logNumber=null;state.browserSubmission=snapshot.submission;state.browserOpponents=opponents;$('match-panel').hidden=true;$('opponent-deck-panel').hidden=true;$('results-empty').hidden=false;$('results-table-wrap').hidden=true;$('simulation-progress').hidden=false;$('simulation-progress').value=0;setView('results');updateNavigation();renderRevertButton();$('status').textContent='Starting simulations against '+opponents.length+' tournament player'+(opponents.length===1?'â€¦':'sâ€¦');worker().postMessage({type:'simulate',submission:state.browserSubmission,opponents:state.browserOpponents,games:+$('games').value,actionLimit:+$('action-limit').value})}catch(error){state.running=false;renderRevertButton();$('status').textContent=error.message;setView('program')}}
function revertToPreviousRun(){const previous=state.currentRun?.previous;if(!previous||state.running)return;restoreSimulationRun(previous);state.revertLockRevision=state.editorRevision;renderRevertButton();startBrowserSimulation()}
$('revert-to-previous-run').addEventListener('click',revertToPreviousRun);
worker().addEventListener('message',event=>{const data=event.data;if(data.type!=='complete'||!state.pendingRun)return;const pending=state.pendingRun,record=simulationRunRecord(pending.snapshot,data.matches);state.simulationHistory[state.deckKey]=record;saveSimulationHistory();state.currentRun={record,previous:pending.previous};state.pendingRun=null;renderRevertButton()});
