function logCardReference(cardId){return '<span class="log-card-reference" tabindex="0" data-tournament-card-preview="'+esc(cardId)+'">'+esc(name(cardId))+'</span>'}
 function richBattleLine(event,player,drawnCardIds=[]){const [who,detail='']=event.split(' | '),label=esc(player(who));if(detail==='turn_start')return label+' begins their turn.';if(detail==='draw')return label+' draws '+(drawnCardIds.length===1?logCardReference(drawnCardIds[0]):'a card')+'.';if(detail.startsWith('draw_many:')){if(!drawnCardIds.length)return label+' draws '+detail.split(':')[1]+' cards.';if(drawnCardIds.length===1)return label+' draws '+logCardReference(drawnCardIds[0])+'.';const count=detail.split(':')[1];return label+' draws '+drawnCardsReference(count+' cards',drawnCardIds,who,player)+'.'}if(detail.startsWith('triggered_draw:')){const source=detail.split(':')[1],subject=drawnCardIds.length===1?logCardReference(drawnCardIds[0]):drawnCardIds.length?drawnCardsReference(drawnCardIds.length+' cards',drawnCardIds,who,player):'a card';return label+' draws '+subject+' from '+logCardReference(source)+'.'}if(detail.startsWith('play:'))return label+' plays '+logCardReference(detail.split(':')[1])+'.';if(detail.startsWith('flux_gain_prevented:')){const [,amount,cardId,outcome]=detail.split(':'),ending=outcome==='deleted'?' and is deleted.':'.';return label+' would gain '+amount+' Flux, but '+logCardReference(cardId)+' prevents it'+ending}if(detail.startsWith('flux:')){const [,amount,current,source]=detail.split(':'),value=Number(amount);if(!value)return '';const sentence=source==='bonus'?'gains '+Math.abs(value)+' additional Flux from '+logCardReference(detail.split(':')[4])+'.':(value>0?'gains ':'loses ')+Math.abs(value)+' Flux.';return label+' '+sentence+' <span class="log-total">('+current+'/20)</span>'}if(detail.startsWith('sync:')){const [,amount,current]=detail.split(':'),value=Number(amount);if(!value)return '';return label+' '+(value>0?'gains ':'loses ')+Math.abs(value)+' Sync. <span class="log-total">('+current+'/20)</span>'}if(detail==='end_turn_effect')return label+' ended their turn from a card effect.';if(detail==='end_turn_action')return label+' ended their turn.';if(event.startsWith('system | battle_end:')){const [,winner,reason]=event.split(':');return winner==='draw'?'The battle ended in a draw ('+esc(reason)+').':esc(player(winner))+' won by '+esc(reason)+'.'}return ''}
readableBattleEvent=event=>richBattleLine(event,playerLabel);
tournamentNarration=(event,first,second)=>richBattleLine(event,id=>id==='first'?first:second);
renderLogDisplay=function(){const turns=state.logTurns||[],visible=state.logMode==='turns'?(turns[state.logTurnIndex]||[]):turns.flat();$('log').innerHTML=visible.join('<br>');const battle='Battle #'+state.logBattleNumber;if(state.logMode!=='turns'){$('log-controls').innerHTML='<div class="log-summary"><strong>'+battle+'</strong><button data-log-mode="turns">View Turns</button></div>';return}const first=state.logTurnIndex===0,last=state.logTurnIndex===turns.length-1;$('log-controls').innerHTML='<div class="log-summary"><strong>'+battle+', Turn '+(state.logTurnIndex+1)+' of '+turns.length+'</strong><button data-log-mode="full">Show Full Log</button></div><div class="log-nav"><button class="primary" data-log-turn="-1" '+(first?'disabled':'')+'>← Prev Turn</button><button class="primary next-turn" data-log-turn="1" '+(last?'disabled':'')+'>Next Turn →</button></div>'}
