/* Keep the final replay handler self-contained: earlier UI compatibility
 * overrides also used `first` and `second`, which made their closures brittle. */
function installLegacyDrawMetadata(Battle){if(Battle.prototype.__cybernetDrawMetadata)return;const originalDraw=Battle.prototype.draw,originalNote=Battle.prototype.note,originalRecord=Battle.prototype.record,originalSnapshot=Battle.prototype.snapshot;Battle.prototype.snapshot=function(player,phase){originalSnapshot.call(this,player,phase);const snapshot=this.turnSnapshots?.at(-1);if(snapshot?.player===player.id){snapshot.deck=player.deck.map(card=>card.definition.card_id);snapshot.ordered=true}};Battle.prototype.draw=function(player,narrate=true){const cardId=player.deck[0]?.definition?.card_id,result=originalDraw.call(this,player,narrate);if(!result)return result;this.__cybernetPendingDraws=this.__cybernetPendingDraws||{};if(narrate){this.drawEvents=this.drawEvents||[];this.drawEvents.push({eventIndex:this.log.length-1,player:player.id,cards:[cardId]})}else if(cardId){const cards=this.__cybernetPendingDraws[player.id]||(this.__cybernetPendingDraws[player.id]=[]);cards.push(cardId)}return result};Battle.prototype.note=function(text){originalNote.call(this,text);const[who,detail='']=text.split(' | ');if(detail==='opening_hand'){if(this.__cybernetPendingDraws)delete this.__cybernetPendingDraws[who];return}if(detail.startsWith('draw_many:')||detail.startsWith('triggered_draw:')){const cards=this.__cybernetPendingDraws?.[who]||[];if(cards.length){this.drawEvents=this.drawEvents||[];this.drawEvents.push({eventIndex:this.log.length-1,player:who,cards:[...cards]})}if(this.__cybernetPendingDraws)delete this.__cybernetPendingDraws[who]}};Battle.prototype.record=function(...args){const record=originalRecord.apply(this,args);if(this.drawEvents)record.drawEvents=this.drawEvents;return record};Object.defineProperty(Battle.prototype,'__cybernetDrawMetadata',{value:true})}
