richBattleLine=function(event,player){const[who,detail='']=event.split(' | '),label=esc(player(who));if(detail.startsWith('uplink:')){const[,amount,current]=detail.split(':');return label+' gains '+Number(amount)+' Uplink. <span class="log-total">('+current+')</span>'}if(detail.startsWith('bandwidth:')){const[,amount,_current,max]=detail.split(':');return label+' gains '+Number(amount)+' Bandwidth. <span class="log-total">('+max+')</span>'}return resourceAwareRichBattleLine(event,player)};

/* A rule row is an editor entry point; press-and-drag remains reorder-only. */
