function ruleEditorCardIds(rule){return [...new Set([...programCardIds(),...standardProgramCards(),...immutableProgramCards(),rule?.condition_card_id,rule?.action_card_id].filter(Boolean))]}
function actionEditorCardIds(rule){const ids=rule?.action_type==='activate_immutable_card'?immutableProgramCards():standardProgramCards();return [...new Set([...ids,rule?.action_card_id].filter(Boolean))]}
