const deleteRuleForEditor=removeRuleFromProgram;removeRuleFromProgram=function(index){if(index<0||index>=state.rules.length)return;if(state.editingRuleIndex===index)state.editingRuleIndex=undefined;else if(Number.isInteger(state.editingRuleIndex)&&state.editingRuleIndex>index)state.editingRuleIndex-=1;deleteRuleForEditor(index)};
