/* Card-face glossary help. Definitions are presentation summaries supplied by
 * the server; named-card references use the live card catalog itself. */
state.keywordDefinitions=[];
let activeCardTerm=null;
function cardDefinitionSummary(definition){return [definition.card_kind_label,definition.keyword_line,definition.effect].filter(Boolean).map(value=>{const text=String(value).trim();return /[.!?]$/.test(text)?text:text+'.'}).join(' ')}
function cardTermCandidates(current){const candidates=[];for(const entry of state.keywordDefinitions||[])for(const alias of entry.aliases||[entry.title])candidates.push({key:'term:'+entry.title,title:entry.title,alias:String(alias),definition:entry.definition,protect:false});for(const definition of state.pool){const displayName=String(definition.display_name||'').trim();if(!displayName)continue;const self=definition.card_id===current?.card_id;candidates.push({key:'card:'+definition.card_id,title:displayName,alias:displayName,card_id:definition.card_id,definition:self?'':cardDefinitionSummary(definition),protect:self})}return candidates.sort((left,right)=>right.alias.length-left.alias.length||Number(Boolean(right.card_id))-Number(Boolean(left.card_id)))}
function isCardTermBoundary(text,index,length){const before=index>0?text[index-1]:'',after=index+length<text.length?text[index+length]:'';return !/[A-Za-z0-9]/.test(before)&&!/[A-Za-z0-9]/.test(after)}
function nextCardTermMatch(text,offset,candidates,seen){let best=null;for(const candidate of candidates){if(!candidate.protect&&seen.has(candidate.key))continue;let index=text.indexOf(candidate.alias,offset);while(index>=0&&!isCardTermBoundary(text,index,candidate.alias.length))index=text.indexOf(candidate.alias,index+1);if(index<0)continue;if(!best||index<best.index||(index===best.index&&candidate.alias.length>best.candidate.alias.length))best={candidate,index}}return best}
function decorateCardTextNode(node,candidates,seen){const text=node.nodeValue||'';let offset=0,changed=false;const fragment=document.createDocumentFragment();while(offset<text.length){const match=nextCardTermMatch(text,offset,candidates,seen);if(!match)break;const {candidate,index}=match;if(index>offset)fragment.append(document.createTextNode(text.slice(offset,index)));const matched=text.slice(index,index+candidate.alias.length);if(candidate.protect){fragment.append(document.createTextNode(matched))}else{const term=document.createElement('span');term.className='card-term';term.tabIndex=0;term.dataset.termTitle=candidate.title;term.dataset.termDefinition=candidate.definition;if(candidate.card_id)term.dataset.termCardId=candidate.card_id;term.textContent=matched;fragment.append(term);seen.add(candidate.key)}offset=index+candidate.alias.length;changed=true}if(!changed)return;if(offset<text.length)fragment.append(document.createTextNode(text.slice(offset)));node.replaceWith(fragment)}
function enhanceCardTerms(face){if(!(face instanceof Element)||face.dataset.cardTermsEnhanced==='true'||!state.keywordDefinitions?.length)return;const title=face.querySelector('.card-titlebar h4')?.textContent?.trim(),current=state.pool.find(definition=>definition.display_name===title),candidates=cardTermCandidates(current),seen=new Set;for(const section of face.querySelectorAll('.card-typebar,.card-rules')){const walker=document.createTreeWalker(section,NodeFilter.SHOW_TEXT);const nodes=[];while(walker.nextNode())if(!walker.currentNode.parentElement?.closest('.card-term'))nodes.push(walker.currentNode);for(const node of nodes)decorateCardTextNode(node,candidates,seen)}face.dataset.cardTermsEnhanced='true'}
function enhanceCardTermsWithin(root){if(root instanceof Element&&root.matches('.builder-card'))enhanceCardTerms(root);if(root?.querySelectorAll)root.querySelectorAll('.builder-card').forEach(enhanceCardTerms)}
function positionCardTermTooltip(){if(!activeCardTerm)return;const {trigger,tooltip}=activeCardTerm,rect=trigger.getBoundingClientRect(),gap=8,width=tooltip.offsetWidth,height=tooltip.offsetHeight;let left=Math.min(Math.max(12,rect.left),window.innerWidth-width-12),top=rect.bottom+gap;if(top+height>window.innerHeight-12)top=Math.max(12,rect.top-height-gap);tooltip.style.left=left+'px';tooltip.style.top=top+'px'}
function showCardTermTooltip(trigger,pinned=false){if(activeCardTerm?.trigger===trigger){activeCardTerm.pinned=activeCardTerm.pinned||pinned;positionCardTermTooltip();return}hideCardTermTooltip(true);const tooltip=document.createElement('div');tooltip.id='card-term-tooltip';tooltip.className='card-term-tooltip';tooltip.setAttribute('role','tooltip');const cardId=trigger.dataset.termCardId;if(cardId){tooltip.classList.add('card-preview-tooltip');tooltip.innerHTML=tournamentCardPreview(cardId)}else{const heading=document.createElement('strong'),definition=document.createElement('span');heading.textContent=trigger.dataset.termTitle||trigger.textContent;definition.textContent=trigger.dataset.termDefinition||'';tooltip.append(heading,definition)}document.body.append(tooltip);trigger.setAttribute('aria-describedby',tooltip.id);activeCardTerm={trigger,tooltip,pinned};requestAnimationFrame(positionCardTermTooltip)}
