document.addEventListener('click',event=>{const term=event.target.closest?.('.card-term');if(term){event.preventDefault();event.stopPropagation();if(activeCardTerm?.trigger===term&&activeCardTerm.pinned)hideCardTermTooltip(true);else showCardTermTooltip(term,true);return}hideCardTermTooltip(true)},true);
