/* Tournament deep links identify the immutable snapshot, matchup, battle, and
 * displayed turn. A new latest tournament cannot silently change an old link
 * into a different battle. */
function tournamentLinkInteger(value){const parsed=Number(value);return Number.isSafeInteger(parsed)&&parsed>0?parsed:null}
function tournamentUrlTarget(){const params=new URLSearchParams(location.search);return{snapshot:params.get('tournament')||'',matchup:params.get('matchup')||'',battle:tournamentLinkInteger(params.get('battle')),turn:tournamentLinkInteger(params.get('turn')),page:tournamentLinkInteger(params.get('page'))}}
function tournamentShareUrl({matchupId,battle,turn,page}={}){const url=new URL(location.href),params=new URLSearchParams,snapshot=tournamentState.data?.snapshot_id;if(snapshot)params.set('tournament',snapshot);if(matchupId)params.set('matchup',String(matchupId));if(tournamentLinkInteger(battle))params.set('battle',String(battle));if(tournamentLinkInteger(turn)&&tournamentLinkInteger(battle))params.set('turn',String(turn));if(tournamentLinkInteger(page)&&matchupId)params.set('page',String(page));url.search=params.toString();url.hash='';return url.href}
function tournamentReplaceUrl(options={}){if(!tournamentState.data?.snapshot_id)return;const url=new URL(tournamentShareUrl(options));history.replaceState(history.state,'',url.pathname+url.search+url.hash)}
function tournamentCopyButton(options){const href=tournamentShareUrl(options);return'<button class="tournament-copy-link" type="button" data-tournament-copy-link="'+esc(href)+'">Copy Link</button>'}
async function copyTournamentLink(href){try{await copyExportCode(href);showToast('Tournament link copied to your clipboard.')}catch(error){showToast('Could not copy the tournament link. '+(error.message||String(error)))}}
function tournamentCurrentMatchupId(){return tournamentState.selectedMatchup?.matchup_id||tournamentState.data?.matchups?.[tournamentState.matchIndex]?.matchup_id||''}
function tournamentTurnIndexForNumber(number){const events=tournamentState.rawTurns||[],target=tournamentLinkInteger(number);if(!target)return 0;const exact=events.findIndex((_,index)=>displayedTurnNumber(events,index)===target);return exact>=0?exact:Math.max(0,Math.min(events.length-1,target-1))}
