function tournamentSortedSummaryPairs(){const data=tournamentState.data||{},standings=data.standings||[],rank=new Map(standings.map((row,index)=>[String(row.discord_user_id),index]));return(data.matchups||[]).map((pair,index)=>({pair,index})).sort((left,right)=>{const leftRanks=[rank.get(String(left.pair.first_discord_user_id)),rank.get(String(left.pair.second_discord_user_id))].map(value=>value??Number.MAX_SAFE_INTEGER),rightRanks=[rank.get(String(right.pair.first_discord_user_id)),rank.get(String(right.pair.second_discord_user_id))].map(value=>value??Number.MAX_SAFE_INTEGER);return Math.min(...leftRanks)-Math.min(...rightRanks)||Math.max(...leftRanks)-Math.max(...rightRanks)})}
const baseRenderTournamentResultsForLinks=renderTournamentResults;
renderTournamentResults=function(){baseRenderTournamentResultsForLinks();const panel=tournamentPanel(),pairings=tournamentSortedSummaryPairs(),body=[...panel.querySelectorAll('table tbody')].at(-1),rows=body?[...body.querySelectorAll('tr')]:[];if(body&&tournamentState.logsAvailable===true){rows.forEach((row,index)=>{const pair=pairings[index]?.pair;if(!pair?.matchup_id)return;row.removeAttribute('data-tournament-match');row.dataset.tournamentMatchId=pair.matchup_id})}tournamentReplaceUrl()}
const baseRenderTournamentMatchForLinks=renderTournamentMatch;
async function renderTournamentMatchById(matchupId,requestedPage){const id=String(matchupId||''),summary=tournamentState.data?.matchups?.find(pair=>String(pair.matchup_id)===id),index=tournamentState.data?.matchups?.findIndex(pair=>String(pair.matchup_id)===id)??-1;if(!summary||index<0)return;const totalBattles=Number(summary.summary?.battle_count||0),pages=Math.max(1,Math.ceil(totalBattles/25)),page=Math.min(pages,tournamentLinkInteger(requestedPage)||1);tournamentState.battlePage=page-1;await baseRenderTournamentMatchForLinks(index);tournamentState.selectedMatchup=await loadTournamentMatchup(id);tournamentReplaceUrl({matchupId:id,page:tournamentState.battlePage+1})}
