const baseRenderTournamentLogForLinks=renderTournamentLog;
renderTournamentLog=function(){baseRenderTournamentLogForLinks();const panel=tournamentPanel(),matchupId=tournamentCurrentMatchupId(),turn=tournamentCurrentTurnNumber(),showFullLog=panel.querySelector('[data-tournament-log-mode="full"]');if(showFullLog)showFullLog.insertAdjacentHTML('afterend',tournamentCopyButton({matchupId,battle:tournamentState.selectedBattleNumber,turn}));tournamentReplaceUrl({matchupId,battle:tournamentState.selectedBattleNumber,turn})}
