const renderTournamentDeckWithCopy=renderTournamentDeck;
renderTournamentDeck=function(id){renderTournamentDeckWithCopy(id);const panel=tournamentPanel(),back=panel.querySelector('.section-heading [data-tournament-back="results"]');if(back&&!panel.querySelector('[data-tournament-copy-deck]')){const actions=document.createElement('div');actions.className='tournament-deck-actions';back.replaceWith(actions);actions.append(back);actions.insertAdjacentHTML('beforeend','<button type="button" class="tournament-copy-deck" data-tournament-copy-deck="'+esc(id)+'">Copy Deck</button>')}}
const renderTournamentResultsWithCopy=renderTournamentResults;
renderTournamentResults=function(){renderTournamentResultsWithCopy();const table=tournamentPanel().querySelector('.table-scroll table'),head=table?.querySelector('thead tr'),body=table?.querySelector('tbody');if(!head||!body)return;if(![...head.children].some(cell=>cell.textContent?.trim()==='Copy Deck'))head.insertAdjacentHTML('beforeend','<th>Copy Deck</th>');body.querySelectorAll('tr[data-tournament-deck]').forEach(row=>{if(row.querySelector('[data-tournament-copy-deck]'))return;const cell=document.createElement('td');cell.innerHTML='<button type="button" class="tournament-copy-deck tournament-results-copy-deck" data-tournament-copy-deck="'+esc(row.dataset.tournamentDeck)+'">Copy Deck</button>';row.append(cell)})}

/* The chooser is intentionally browser-local. Saved rows use the same
 * drag/reorder model as programming rules, while the import path decodes the
 * compact code that the current browser exports for Discord. */
