function applySavedDeckRecord(record,view='deck'){const owner=String(record?.owner_name||$('owner').value.trim()||savedPlayerName()||'Player'),nameValue=String(record?.name||'Imported Deck');$('owner').value=owner;$('deck-name').value=nameValue;persistPlayerName();state.deck={...(record?.decklist||{})};state.rules=(record?.program||[]).map(rule=>({...rule}));state.defaultAction=record?.default_action||'play_random_card';state.randomEligibleCards=Array.isArray(record?.random_card_ids)?[...record.random_card_ids]:Object.keys(state.deck);state.randomEligibilityConfigured=record?.random_eligibility_configured===undefined?Array.isArray(record?.random_card_ids):record.random_eligibility_configured===true;state.reactions=(record?.reactions||[]).map(rule=>({...rule}));state.selectedRule=undefined;state.deckKey=savedDeckKey(owner,nameValue);resetDeckSession();activateDeck(view);setTimeout(renderDefaultAction,0)}
function loadSavedDeckByKey(key){const saved=loadSavedDecks().find(deck=>savedDeckKey(deck.owner_name,deck.name)===key);if(saved)applySavedDeckRecord(saved,'deck')}
function uniqueSavedDeckName(owner,base){const used=new Set(savedDecksForOwner(owner).map(deck=>deck.name));let candidate=base||'Imported Deck',suffix=2;while(used.has(candidate))candidate=(base||'Imported Deck')+' ('+(suffix++)+')';return candidate}
function startNewDeck(){const owner=$('owner').value.trim(),nameValue=$('deck-name').value.trim();if(!owner){showToast('Enter your name before creating a deck.');return}if(!nameValue){showToast('Give the new deck a name first.');$('deck-name').focus();return}if(loadSavedDecks().some(deck=>savedDeckKey(deck.owner_name,deck.name)===savedDeckKey(owner,nameValue))){showToast('A saved deck already has that name.');return}applySavedDeckRecord({owner_name:owner,name:nameValue,decklist:{},program:[],default_action:'play_random_card',random_card_ids:[],random_eligibility_configured:false,reactions:[]},'deck');$('new-deck-wrap').hidden=true;$('new-deck-hint').hidden=true;$('show-new-deck').textContent='Create a new deck';renderSavedDecks()}

function deleteSavedDeck(key){const decks=loadSavedDecks(),saved=decks.find(deck=>savedDeckKey(deck.owner_name,deck.name)===key);if(!saved)return;if(!window.confirm('Delete saved deck "'+saved.name+'"?'))return;saveSavedDecks(decks.filter(deck=>savedDeckKey(deck.owner_name,deck.name)!==key));if(state.deckKey===key)state.deckKey=null;renderSavedDecks();showToast('Deleted '+saved.name+'.')}
function reorderSavedDecks(fromKey,toKey){if(!fromKey||!toKey||fromKey===toKey)return;const decks=loadSavedDecks(),from=decks.findIndex(deck=>savedDeckKey(deck.owner_name,deck.name)===fromKey),to=decks.findIndex(deck=>savedDeckKey(deck.owner_name,deck.name)===toKey);if(from<0||to<0)return;const [moved]=decks.splice(from,1);decks.splice(to,0,moved);saveSavedDecks(decks);renderSavedDecks()}
function clearSavedDeckDragStyles(){document.querySelectorAll('[data-saved-deck]').forEach(row=>row.classList.remove('saved-deck-dragging','saved-deck-drag-over'))}
