document.addEventListener('drop',event=>{const row=event.target.closest?.('[data-saved-deck]');if(!row||!draggedSavedDeckKey)return;event.preventDefault();reorderSavedDecks(draggedSavedDeckKey,row.dataset.savedDeck);draggedSavedDeckKey=undefined;suppressSavedDeckClick=true;setTimeout(()=>{suppressSavedDeckClick=false},0);clearSavedDeckDragStyles()},true);
