let pointerSavedDeck;
document.addEventListener('pointerdown',event=>{if(event.pointerType==='mouse'||event.target.closest?.('button'))return;const row=event.target.closest?.('[data-saved-deck]');if(!row)return;const pointerId=event.pointerId;pointerSavedDeck={key:row.dataset.savedDeck,row,pointerId,startX:event.clientX,startY:event.clientY,dragging:false};try{row.setPointerCapture(pointerId)}catch(_error){}},true);
document.addEventListener('pointermove',event=>{if(!pointerSavedDeck||pointerSavedDeck.pointerId!==event.pointerId)return;const distance=Math.hypot(event.clientX-pointerSavedDeck.startX,event.clientY-pointerSavedDeck.startY);if(!pointerSavedDeck.dragging&&distance<8)return;if(!pointerSavedDeck.dragging){pointerSavedDeck.dragging=true;pointerSavedDeck.row.classList.add('saved-deck-dragging')}event.preventDefault();const target=document.elementFromPoint(event.clientX,event.clientY)?.closest?.('[data-saved-deck]');document.querySelectorAll('[data-saved-deck]').forEach(candidate=>candidate.classList.remove('saved-deck-drag-over'));if(target&&target.dataset.savedDeck!==pointerSavedDeck.key)target.classList.add('saved-deck-drag-over')},true);
document.addEventListener('pointerup',event=>{if(!pointerSavedDeck||pointerSavedDeck.pointerId!==event.pointerId)return;const current=pointerSavedDeck;const target=document.elementFromPoint(event.clientX,event.clientY)?.closest?.('[data-saved-deck]');if(current.dragging&&target&&target.dataset.savedDeck!==current.key){reorderSavedDecks(current.key,target.dataset.savedDeck);suppressSavedDeckClick=true;setTimeout(()=>{suppressSavedDeckClick=false},0)}current.row.classList.remove('saved-deck-dragging');clearSavedDeckDragStyles();try{current.row.releasePointerCapture(current.pointerId)}catch(_error){}pointerSavedDeck=undefined},true);
