$('show-new-deck').onclick=()=>{const wrap=$('new-deck-wrap');if(wrap.hidden){wrap.hidden=false;$('new-deck-hint').hidden=false;$('deck-name').value='';$('show-new-deck').textContent='Start building';$('deck-name').focus()}else startNewDeck()};$('deck-name').onkeydown=event=>{if(event.key==='Enter'){event.preventDefault();startNewDeck()}};
$('import-discord-code').onclick=async()=>{try{if(!navigator.clipboard?.readText)throw Error('Clipboard access is unavailable in this browser.');const code=await navigator.clipboard.readText();const payload=decodeDiscordCode(code),owner=$('owner').value.trim()||savedPlayerName()||'Player',nameValue=uniqueSavedDeckName(owner,payload.name);payload.owner_name=owner;payload.name=nameValue;$('new-deck-wrap').hidden=true;$('new-deck-hint').hidden=true;$('show-new-deck').textContent='Create a new deck';applySavedDeckRecord(payload,'program');showToast('Imported '+nameValue+'. Start programming your deck.')}catch(error){showToast('Could not load a deck from your clipboard. '+(error.message||String(error)))}};
