/* Target → Quantity editor model. The serialized flat names remain accepted
 * for saved decks and old Discord imports. */
const structuredQuantityLabels={cards_in_deck:'Cards in deck',cards_in_hand:'Cards in hand',cards_on_board:'Cards on board',flux:'Flux',ki:'Ki',bandwidth:'Bandwidth',sync:'Sync'};
const structuredTargetLabels={your:'Your',opponent:"Opponent's"};
const structuredQuantityMap={your:{cards_in_deck:'cards_in_your_deck',cards_in_hand:'cards_in_your_hand',cards_on_board:'cards_on_your_board',flux:'your_flux',ki:'your_ki',bandwidth:'your_bandwidth',sync:'your_sync'},opponent:{cards_in_deck:'cards_in_opponent_deck',cards_in_hand:'cards_in_opponent_hand',cards_on_board:'cards_on_opponent_board',flux:'opponent_flux',ki:'opponent_ki',bandwidth:'opponent_bandwidth',sync:'opponent_sync'}};
const structuredQuantityParts={};for(const target of Object.keys(structuredQuantityMap))for(const quantity of Object.keys(structuredQuantityMap[target]))structuredQuantityParts[structuredQuantityMap[target][quantity]]={target,quantity};
Object.assign(quantityLabels,{cards_in_opponent_deck:"opponent's deck",cards_on_your_board:'your board',cards_on_opponent_board:"opponent's board",opponent_ki:"opponent's Ki",opponent_bandwidth:"opponent's Bandwidth"});
const conditionTextBeforeOpponentBoard=conditionText;
conditionText=function(type,threshold,cardId,cardCondition,quantity,comparison,quantityThreshold){if(type==='card_is'&&cardCondition==='on_opponent_side_of_board')return name(cardId)+' is on your opponent\'s side of the board';return conditionTextBeforeOpponentBoard(type,threshold,cardId,cardCondition,quantity,comparison,quantityThreshold)};
function selectedStructuredQuantity(){const target=$('condition-target').value||'your',quantity=$('condition-quantity').value||'cards_in_deck';return structuredQuantityMap[target]?.[quantity]}
function structuredPartsForRule(rule){if(rule?.quantity_target&&structuredQuantityMap[rule.quantity_target]?.[rule.quantity])return {target:rule.quantity_target,quantity:rule.quantity};return structuredQuantityParts[rule?.quantity]||{target:'your',quantity:'cards_in_deck'}}
quantityConditionText=function(rule){const parts=structuredPartsForRule(rule),label=rule?.quantity_target?structuredTargetLabels[parts.target]+' '+structuredQuantityLabels[parts.quantity]:quantityLabels[rule?.quantity];return label+' is '+comparisonLabels[rule?.comparison_operator]+' '+rule?.quantity_threshold};
comparisonQuantityForType=function(type){return comparisonConditionQuantities[type]||(type==='quantity_compare'?selectedStructuredQuantity():undefined)};
renderComparisonRuleSentence=function(){const type=$('condition-type').value,quantity=comparisonQuantityForType(type),action=$('action-type').value,actionCard=$('action-card').value;if(type==='quantity_compare'){const target=$('condition-target').value||'your',kind=$('condition-quantity').value||'cards_in_deck';$('rule-sentence').textContent='If '+structuredTargetLabels[target]+' '+structuredQuantityLabels[kind]+' is '+comparisonLabels[$('comparison-operator').value]+' '+$('quantity-threshold').value+', '+actionText(action,actionCard)+'.'}else if(quantity){$('rule-sentence').textContent='If '+quantityLabels[quantity]+' is '+comparisonLabels[$('comparison-operator').value]+' '+$('quantity-threshold').value+', '+actionText(action,actionCard)+'.'}else $('rule-sentence').textContent=ruleText(type,$('condition-energy').value,$('condition-card').value,action,actionCard,$('card-condition').value)};
renderQuantityRuleSentence=renderComparisonRuleSentence;
for(const legacyType of ['own_victory_points_at_most','opponent_victory_points_at_most','opponent_victory_points_at_least','opponent_sync_at_most']){if(!conditionSelect.querySelector('option[value="'+legacyType+'"]')){const option=document.createElement('option');option.value=legacyType;option.textContent=legacyType.replaceAll('_',' ');option.hidden=true;conditionSelect.append(option)}}
renderComparisonConditionParameters=function(){const type=$('condition-type').value,isQuantity=type==='quantity_compare',isComparison=Boolean(comparisonQuantityForType(type));$('action-condition-prefix').textContent=type==='if_able'?'If able,':'If';$('quantity-target-wrap').hidden=!isQuantity;$('quantity-wrap').hidden=!isQuantity;$('comparison-wrap').hidden=!isComparison;$('quantity-threshold-wrap').hidden=!isComparison;$('condition-card-wrap').hidden=type!=='card_is';$('card-condition-wrap').hidden=type!=='card_is';$('condition-energy-wrap').hidden=true;renderComparisonRuleSentence()};
const beginRuleEditWithFlatQuantity=beginRuleEdit;
beginRuleEdit=function(index){beginRuleEditWithFlatQuantity(index);const rule=state.rules[index];if(rule?.condition_type==='quantity_compare'){const parts=structuredPartsForRule(rule);$('condition-target').value=parts.target;$('condition-quantity').value=parts.quantity;renderComparisonRuleSentence()}};
const tournamentRuleTextBeforeOpponentBoard=tournamentRuleText;
tournamentRuleText=function(rule){if(rule?.condition_type==='card_is'&&rule.card_condition==='on_opponent_side_of_board')return 'If '+tournamentCardName(rule.condition_card_id)+' is on your opponent\'s side of the board, '+tournamentRuleActionText(rule)+'.';return tournamentRuleTextBeforeOpponentBoard(rule)};
readRuleFromEditor=function(){const conditionType=$('condition-type').value,actionType=$('action-type').value,rule={condition_type:conditionType,action_type:actionType};if(conditionType==='card_is'){rule.condition_card_id=$('condition-card').value;rule.card_condition=$('card-condition').value}else if(conditionType==='quantity_compare'){const threshold=Number($('quantity-threshold').value);if(!Number.isSafeInteger(threshold)||threshold<0){$('status').textContent='Quantity conditions need a whole number of 0 or more.';return}rule.quantity_target=$('condition-target').value;rule.quantity=$('condition-quantity').value;rule.comparison_operator=$('comparison-operator').value;rule.quantity_threshold=threshold}else if(conditionType!=='if_able')rule.energy_threshold=+$('condition-energy').value;if(['play_named_card','activate_immutable_card'].includes(actionType))rule.action_card_id=$('action-card').value;return rule};
exportDeckCode=function(){const ids=state.pool.map(card=>card.card_id),index=new Map(ids.map((id,i)=>[id,i])),bytes=ids.map(id=>state.deck[id]||0),conditions={if_able:0,card_in_hand:1,own_victory_points_at_most:2,opponent_victory_points_at_most:3,opponent_sync_at_most:4,opponent_victory_points_at_least:5,card_is:6,quantity_compare:7},quantities={cards_in_your_deck:0,cards_in_your_hand:1,cards_in_opponent_hand:2,your_flux:3,opponent_flux:4,your_sync:5,opponent_sync:6,your_ki:7,your_bandwidth:8,cards_in_opponent_deck:9,cards_on_your_board:10,cards_on_opponent_board:11,opponent_ki:12,opponent_bandwidth:13},comparisons={'<':0,'<=':1,'=':2,'>=':3,'>':4},actions={play_named_card:0,play_random_card:1,end_turn:2,activate_immutable_card:3};bytes.push(state.rules.length);for(const rule of state.rules){const condition=conditions[rule.condition_type],action=actions[rule.action_type];if(condition===undefined||action===undefined)throw Error('This deck has an unsupported rule.');bytes.push((condition<<4)|action);if(condition===1)bytes.push(index.get(rule.condition_card_id));else if(condition===6)bytes.push(index.get(rule.condition_card_id),rule.card_condition==='on_your_side_of_board'?1:rule.card_condition==='on_opponent_side_of_board'?2:0);else if(condition===7){const quantity=rule.quantity_target?structuredQuantityMap[rule.quantity_target]?.[rule.quantity]:rule.quantity,threshold=Number(rule.quantity_threshold);if(quantities[quantity]===undefined||!Number.isInteger(threshold)||threshold<0||threshold>65535)throw Error('Quantity conditions must use a valid target, quantity, and whole number from 0 through 65,535.');bytes.push(quantities[quantity],comparisons[rule.comparison_operator],threshold>>8,threshold&255)}else if(condition!==0)bytes.push(rule.victory_points_threshold??rule.energy_threshold);if(action===0||action===3)bytes.push(index.get(rule.action_card_id));}bytes.push(state.reactions.length);for(const rule of state.reactions){const threshold=Number(rule.quantity_threshold);bytes.push(0,comparisons[rule.comparison_operator],threshold>>8,threshold&255,index.get(rule.action_card_id));}const mask=eligibleRandomCards().reduce((total,id)=>total|(1<<index.get(id)),0);bytes.push(state.defaultAction==='end_turn'?1:0,mask>>8,mask&255);return (state.exportDeckCodePrefix||'CD5')+'.'+(state.exportFormatId||state.formatId||'inaugural')+'.'+btoa(String.fromCharCode(...bytes)).replaceAll('+','-').replaceAll('/','_').replaceAll('=','')};
$('condition-type').onchange=renderComparisonConditionParameters;$('condition-target').onchange=renderComparisonRuleSentence;$('condition-quantity').onchange=renderComparisonRuleSentence;$('comparison-operator').onchange=renderComparisonRuleSentence;$('quantity-threshold').oninput=renderComparisonRuleSentence;$('action-type').onchange=()=>{renderRuleSelectors();renderComparisonRuleSentence()};$('action-card').onchange=renderComparisonRuleSentence;renderComparisonConditionParameters();

/* Ordered combo actions. The special selector value is UI-only; saved and
 * simulated submissions use action_type=play_combo plus action_card_ids. */
const comboActionOption='__combo__';
const comboSelectOption='__select__';
state.comboSelection=[];
state.comboCancelIfCardNotPlayed=false;
state.comboOnlyWhenAllCardsInHand=false;
$('action-type').onchange=()=>{if($('action-type').value!=='play_named_card'){state.comboSelection=[];state.comboCancelIfCardNotPlayed=false;state.comboOnlyWhenAllCardsInHand=false;$('combo-cancel-if-not-played').checked=false;$('combo-only-when-all-cards-in-hand').checked=false}else{$('action-card').value=comboActionOption;state.comboCancelIfCardNotPlayed=false;state.comboOnlyWhenAllCardsInHand=false;$('combo-cancel-if-not-played').checked=false;$('combo-only-when-all-cards-in-hand').checked=false}renderRuleSelectors();renderComparisonRuleSentence()};
$('action-card').onchange=()=>{if($('action-card').value!==comboActionOption){state.comboSelection=[];state.comboCancelIfCardNotPlayed=false;state.comboOnlyWhenAllCardsInHand=false;$('combo-cancel-if-not-played').checked=false;$('combo-only-when-all-cards-in-hand').checked=false}renderRuleSelectors();renderComparisonRuleSentence()};
$('combo-cancel-if-not-played').onchange=()=>{state.comboCancelIfCardNotPlayed=$('combo-cancel-if-not-played').checked===true;markEditorChanged();renderComparisonRuleSentence()};
$('combo-only-when-all-cards-in-hand').onchange=()=>{state.comboOnlyWhenAllCardsInHand=$('combo-only-when-all-cards-in-hand').checked===true;markEditorChanged();renderComparisonRuleSentence()};
function comboCardIds(extraIds=[]){const ids=[...programCardIds(),...extraIds];return [...new Set(ids)].filter(id=>!isImmutableCard(id)&&(card(id)?.card_kind!=='glitch'||card(id)?.signature===true))}
function comboActionTextForIds(ids){const names=(ids||[]).map(name);return names.length?'play combo: '+names.join(' -> '):'play combo'}
const comboBaseActionText=actionText;
actionText=function(type,cardId){if(cardId===comboSelectOption)return 'choose a card';if(type==='play_combo'||cardId===comboActionOption)return comboActionTextForIds(state.comboSelection);return comboBaseActionText(type,cardId)};
function comboOptionList(select,ids,selected){select.innerHTML='<option value="'+comboSelectOption+'" '+(selected===comboSelectOption?'selected':'')+'>-- Select --</option><option value="'+comboActionOption+'" '+(selected===comboActionOption?'selected':'')+'>*Combo*</option>'+ids.map(id=>'<option value="'+esc(id)+'" '+(id===selected?'selected':'')+'>'+esc(name(id))+'</option>').join('')}
