$('start-new-deck').onclick=()=>openDeckSetup('new');$('import-discord-code').onclick=()=>openDeckSetup('import');$('create-deck').onclick=()=>{if(deckSetupMode==='import')importDeckFromClipboard();else if(deckSetupMode==='new')startNewDeck()};$('owner').oninput=renderSavedDecks;$('deck-name').onkeydown=event=>{if(event.key==='Enter'){event.preventDefault();$('create-deck').click()}};

