  if(!builder||builder.dataset.rowsArranged==='true')return;
  const conditionFields=document.createElement('div');
  conditionFields.className='rule-builder-fields condition-fields';
  const actionFields=document.createElement('div');
  actionFields.className='rule-builder-fields action-fields';
  const conditionIds=['action-condition-prefix','condition-card-wrap','card-condition-wrap','condition-energy-wrap','quantity-target-wrap','quantity-wrap','comparison-wrap','quantity-threshold-wrap'];
  for(const id of conditionIds){const element=$(id);if(element)conditionFields.append(element)}
  const actionElements=[builder.querySelector('.then-prefix'),$('action-type')?.parentElement,$('action-card-wrap')].filter(Boolean);
  for(const element of actionElements)actionFields.append(element);
