initializeBrowserDeckMigration=async function(){/* D1 login owns the migration barrier. */};
const finalRawCloudExport=typeof $('export-deck').onclick==='function'?$('export-deck').onclick:null;
$('export-deck').onclick=async()=>{try{await cloudFlushSave();if(state.cloudUnsaved)cloudStatus('Exporting an unsaved in-memory draft; it is not stored in D1.','error');if(finalRawCloudExport)await finalRawCloudExport()}catch(error){cloudStatus('Exporting this draft while it is not saved in D1. '+cloudErrorMessage(error),'error');if(finalRawCloudExport)await finalRawCloudExport()}};
$('export-deck-results').onclick=()=>$('export-deck').click();
$('cloud-retry').onclick=()=>{state.cloudAutosavePaused=false;state.cloudUnsaved=false;state.cloudPending=true;cloudWritePending().catch(()=>{})};
$('cloud-reload-copy').onclick=()=>{if(state.cloudConflict)cloudOpenRecord(state.cloudConflict,'deck')};
$('cloud-save-new').onclick=async()=>{try{const source=cloudSubmissionRecord(),metadata=cloudFormatMetadata(),owner=state.cloudPlayer.display_name,name=cloudUniqueName((source.name||$('deck-name').value)+' (conflict copy)'),created=await state.cloudStore.create({name,draft:{...source,owner_name:owner,name},submission_schema_version:metadata.submission_schema_version,format_fingerprint:metadata.format_fingerprint});$('cloud-conflict').hidden=true;cloudApplyNewRecord(created,'deck');cloudStatus('Saved your draft as '+name+'.')}catch(error){cloudStatus('Could not save the conflict as a new deck. '+cloudErrorMessage(error),'error')}};
$('cloud-return-list').onclick=async()=>{await cloudFlushSave().catch(()=>{});$('cloud-conflict').hidden=true;state.cloudConflict=null;state.cloudAutosavePaused=false;state.cloudRecord=null;state.deckReady=false;$('deck-setup').hidden=false;$('workflow-nav').hidden=true;cloudSetUi(true);renderSavedDecks()};
$('player-login').onclick=cloudLogin;
$('owner').onkeydown=event=>{if(event.key==='Enter'&&!state.cloudReady){event.preventDefault();cloudLogin()}};
$('switch-player').onclick=async()=>{await cloudFlushSave().catch(()=>{});state.cloudStore?.clearSession();state.cloudReady=false;state.cloudPlayer=null;state.cloudRecords=[];state.cloudRecord=null;state.deckReady=false;$('deck-setup').hidden=false;$('workflow-nav').hidden=true;$('owner').disabled=false;$('owner').value='';cloudSetUi(false);renderSavedDecks();cloudStatus('Enter another player name to switch.');};
const finalRawStartBrowserSimulation=startBrowserSimulation;startBrowserSimulation=function(){if(state.cloudUnsaved)cloudStatus('Simulation is using an in-memory draft that is not stored in D1.','error');return finalRawStartBrowserSimulation()};
cloudSetUi(Boolean(state.cloudReady));renderSavedDecks();

/* Final reaction editor binding. */
renderReactionProgram=function(){const ids=reactionCardsForTrigger($('reaction-trigger').value);$('add-reaction').disabled=!ids.length;$('add-reaction').textContent=state.editingReactionIndex===undefined?'Add reaction':'Update reaction';$('cancel-reaction-edit').hidden=state.editingReactionIndex===undefined;renderReactionEditor();$('reactions').innerHTML=state.reactions.map((rule,index)=>'<li data-reaction-row="'+index+'"><span class="rule-priority">'+(index+1)+'</span><span class="rule-copy"><strong>'+esc(reactionRuleDescription(rule))+'</strong><small>'+(index===0?'Highest priority reaction.':'Runs after the reactions above.')+'</small></span><button type="button" data-edit-reaction="'+index+'" aria-label="Edit reaction '+(index+1)+'">✎</button><button type="button" data-move-reaction="'+index+'" data-reaction-direction="-1" '+(index===0?'disabled':'')+' aria-label="Move reaction '+(index+1)+' up">↑</button><button type="button" data-move-reaction="'+index+'" data-reaction-direction="1" '+(index+1===state.reactions.length?'disabled':'')+' aria-label="Move reaction '+(index+1)+' down">↓</button><button type="button" data-remove-reaction="'+index+'" aria-label="Delete reaction '+(index+1)+'">×</button></li>').join('')||'<li class="empty-state">No reactions yet.</li>'};
$('reaction-trigger').onchange=()=>{if($('reaction-trigger').value!=='own_agent_would_be_deleted'){state.reactionAgentChoice=reactionCardsOption;state.reactionAgentSelection=[]}else if(state.reactionAgentChoice===undefined)state.reactionAgentChoice=reactionCardsOption;renderReactionProgram()};
$('reaction-agent').onchange=()=>{state.reactionAgentChoice=$('reaction-agent').value;if(state.reactionAgentChoice===reactionCardsOption)state.reactionAgentSelection=[];else state.reactionAgentSelection=[state.reactionAgentChoice];renderReactionAgentPicker()};
$('cancel-reaction-edit').onclick=()=>{resetReactionEditor();renderReactionProgram()};
$('add-reaction').onclick=()=>{const trigger=$('reaction-trigger').value,ids=reactionCardsForTrigger(trigger),actionCardId=$('reaction-card').value;if(!ids.length||!actionCardId)return;if(state.editingReactionIndex===undefined&&state.reactions.length>=10){$('status').textContent='A reaction program can have at most 10 rules.';return}let rule;if(trigger==='own_agent_would_be_deleted'){const agents=state.reactionAgentChoice===reactionCardsOption?[...(state.reactionAgentSelection||[])]:[state.reactionAgentChoice];if(!agents.length){$('status').textContent='Select at least one Agent for this deletion reaction.';return}rule={trigger_type:trigger,comparison_operator:'=',quantity_threshold:1,action_card_id:actionCardId,agent_card_ids:agents}}else{const threshold=Number($('reaction-threshold').value);if(!Number.isSafeInteger(threshold)||threshold<0){$('status').textContent='Reaction amounts need a whole number of 0 or more.';return}rule={trigger_type:trigger,comparison_operator:$('reaction-comparison').value,quantity_threshold:threshold,action_card_id:actionCardId}}if(state.editingReactionIndex===undefined)state.reactions.push(rule);else state.reactions[state.editingReactionIndex]=rule;resetReactionEditor();renderReactionProgram();persistSelectedDeck()};
renderReactionProgram();
